using AsyncScapeIA.Domain;using TUnit;using TUnit.Assertions;namespace AsyncScapeIA.UnitTests.Domain;public class ArchitectureComponentTests{    [Test]    public async Task ValidateInvariants_requires_primary_owner()    {        var component = ArchitectureComponent.Create(            name: "Payments API",            domain: "Payments",            lifecycleState: LifecycleState.Active);        component.AssignOwnership(new OwnershipAssignment(OwnershipRole.Secondary, Guid.NewGuid()));        await Assert.That(() => component.ValidateInvariants())            .Throws<DomainRuleException>();    }}